CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `Order Details Extended` AS select `Order Details`.`OrderID` AS `OrderID`,`Order Details`.`ProductID` AS `ProductID`,`Products`.`ProductName` AS `ProductName`,`Order Details`.`UnitPrice` AS `UnitPrice`,`Order Details`.`Quantity` AS `Quantity`,`Order Details`.`Discount` AS `Discount`,round(((`Order Details`.`UnitPrice` * `Order Details`.`Quantity`) * (1 - `Order Details`.`Discount`)),2) AS `ExtendedPrice` from (`Products` join `Order Details` on((`Products`.`ProductID` = `Order Details`.`ProductID`)));
